#!/usr/bin/env python3
# writes the stub classes and the stub entries in the manifest.
# change COUNT, run it, commit the result. each clone uses one stub process.
import re

COUNT = 120

java = '''package dev.illclone;

import android.app.Activity;
import android.app.Service;
import android.content.ContentProvider;
import android.content.ContentValues;
import android.content.Intent;
import android.database.Cursor;
import android.net.Uri;
import android.os.IBinder;

// generated by tools/gen_stubs.py, do not edit by hand.
// empty placeholders, one set per stub process. a clone activity is launched "as" one
// of these, then swapped for the real one.
public class Stubs {

    public static class BaseService extends Service {
        @Override
        public IBinder onBind(Intent intent) {
            return null;
        }
    }

    public static class BaseProvider extends ContentProvider {
        @Override public boolean onCreate() { return true; }
        @Override public Cursor query(Uri u, String[] p, String s, String[] a, String o) { return null; }
        @Override public String getType(Uri u) { return null; }
        @Override public Uri insert(Uri u, ContentValues v) { return null; }
        @Override public int delete(Uri u, String s, String[] a) { return 0; }
        @Override public int update(Uri u, ContentValues v, String s, String[] a) { return 0; }
    }

'''
for i in range(COUNT):
    java += f'    public static class A{i} extends Activity {{ }}\n'
    java += f'    public static class S{i} extends BaseService {{ }}\n'
    java += f'    public static class P{i} extends BaseProvider {{ }}\n'
java += '}\n'
open('app/src/main/java/dev/illclone/Stubs.java', 'w').write(java)

xml = ''
for i in range(COUNT):
    # own task affinity so a clone opens in its own window and the main app stays in the background
    xml += f'''        <activity
            android:name=".Stubs$A{i}"
            android:process=":p{i}"
            android:taskAffinity="dev.illclone.slot{i}"
            android:exported="false" />
        <service android:name=".Stubs$S{i}" android:process=":p{i}" android:exported="false" />
        <provider
            android:name=".Stubs$P{i}"
            android:authorities="dev.illclone.stub.p{i}"
            android:process=":p{i}"
            android:exported="false" />
'''
path = 'app/src/main/AndroidManifest.xml'
text = open(path).read()
block = '        <!-- stubs begin -->\n' + xml + '        <!-- stubs end -->'
if '<!-- stubs begin -->' in text:
    text = re.sub(r'        <!-- stubs begin -->.*?<!-- stubs end -->', lambda m: block, text, flags=re.S)
else:
    # first run: replace the hand written stubs
    start = text.index('        <!-- stub process 0 -->')
    end = text.index('    </application>')
    text = text[:start] + block + '\n\n' + text[end:]
open(path, 'w').write(text)
print('wrote', COUNT, 'stubs')
